_schema_doc:
WrapperClass record (JSON), one row per wrapper class. classifierWeights and all utility legs are SOFT scores in [0,1] (never hard categorical) per Pav "the classifiers have weights not hard values." Fields:

{
  "schema_version": "string — e.g. '0.1-phase1', matches repo convention (candidates.json/continuations.json carry schema_version).",
  "id": "string — stable slug, e.g. 'wrapper-overlap', 'marriage', used as the parent-edge target in overlaps[] and provenance trails.",
  "name": "string — canonical handle of the wrapper class.",
  "aka": ["string — synonym set / 'who called it'; the cross-field local names for the same shape (cont 22 §7 construct-study names; §0 C0.1 'same shape named in N traditions'). Each entry may carry {term, tradition, source}."],
  "origin": {
    "howItCameToBe": "string — the procedural-lineage account (cont 18 §1: rings-on-a-tree, each layer the measurable-and-observable compile beneath).",
    "parents": ["string id — declared parent records (cont 25 §5 stubs/receptor-hooks this class attaches to).",],
    "tradition": "string — the tradition/canon it descends from (cont 22 §7 drill: where its actual Kanon lies below the social-protocol layer).",
    "firstNamedBy": "string — earliest attributor/coiner if known ('who called it')."
  },
  "overlaps": [
    {
      "target": "string id — the other wrapper class.",
      "type": "string — typed edge: 'overlap' | 'supersession' | 'break-apart' | 'dormant-resurrection' (cont 25 §2 lifecycle branch between two wrappers).",
      "note": "string — what the overlap produces / how they bridge."
    }
  ],
  "status": "string — SOFT lifecycle position, observer-relative: 'risen' | 'demoted' | 'dormant' | 'resurrected' | 'reinvented' | 'stale' (Pav's vocabulary; maps to cont 20 dormancy + cont 25 §2 branches). May be an array if simultaneously different across domains.",
  "localKernelCanon": "string — the keystone function(s) the class bottoms out into (cont 32 Part B.2 'L0 kernel canon = identifiable keystone functions'; cont 22 §3 Kanon-drill). Names the drill-floor, not just the surface protocol.",
  "netProduct": "string — what the class actually outputs/compiles: the W_C it produces and/or the action-space it sustains (Pav's 'net product').",
  "classifierWeights": {
    "spread": "number [0,1] — SOFT; pool-coverage / marginal diversity contribution (latent_olympics §2; the one genuinely-new, relational dimension).",
    "utility": "number [0,1] — SOFT; the PRIMARY ranking, = utility.score below (carried up for convenience).",
    "legacy": "number [0,1] — SOFT; procedural-lineage depth / compile-on-parent (cont 18; redefined cont 27/latent_olympics §7.1 as distance-to-a-falsification-surviving-anchor, NOT endorsement).",
    "rigor": "number [0,1] — SOFT; falsifiability + tier position + within-tier bar progress (cont 27 §2; carries the dream→fact directionality)."
  },
  "utility": {
    "actionSpaces": {
      "score": "number [0,1] — SOFT; new phantom/constructed action-spaces unlocked (cont 32 Part C internal vs attributed; §PS action-space-as-primitive 'field of latent affordance').",
      "handle": "string — evidence: enumerated new live moves/affordances/questions opened that the prior vocabulary did NOT license (latent_olympics §2 remainder).",
      "judgment": "boolean — true; honest residual: needs AI/human panel, not closed-form."
    },
    "unifier": {
      "score": "number [0,1] — SOFT; previously-separate wrapper classes/traditions bridged into ONE compiled structure (cont 18 §0 'structural unification not new decoration'; cont 25 §6/§7 convergence).",
      "bridgeCount": "integer — degree on overlaps[] resolving to a single structure (mechanical).",
      "passesW_CTest": "boolean — does the bridge pass cont 25 §6 parents-produce-W_C (genuine unification) vs §0 family-resemblance (parallel naming only)?",
      "judgment": "boolean — partly; count is mechanical, the structural test is judged."
    },
    "compression": {
      "score": "number [0,1] — SOFT; THE QUANTIFIABLE LEG. Latent/physical description-length reduction (cont 22 §2 dual-kernel; §IT KL=excess code-length / MDL surrogate / Landauer floor).",
      "mdlDeltaBits": "number — measured/estimated description-length reduction in bits of the corpus the class re-describes (§IT C-IT-6 portable panel: exact on instrumented cases, order-of-magnitude on soft).",
      "judgment": "boolean — false on instrumented cases (computable); the part of utility least judgment-dependent."
    },
    "weights": { "w_a": "number [0,1]", "w_u": "number [0,1]", "w_c": "number [0,1] — SOFT, per-event/per-domain dials; sum to 1." },
    "score": "number [0,1] — utility = w_a*actionSpaces.score + w_u*unifier.score + w_c*compression.score (the PRIMARY ranking; weighted combination, NOT a crowned scalar — feeds the Pareto front, latent_olympics §2)."
  },
  "tier": "string — cont 27 §2 epistemic tier: 'Tier 1' | 'Tier 2' | 'Tier 3'.",
  "pipeline": {
    "state": "string — git-like: 'submitted' | 'under-review' | 'challenged' | 'appealed' | 'graduated' | 'demoted' | 'dormant' (§9.3).",
    "provenanceTrail": "string — declared at submit per latent_olympics §5 (tradition + parent ids + canon built on); 'drill stops here' is legible/rate-able.",
    "issues": ["{id, type ∈ {provenance-laundering, bad-faith-rendering, inflated-utility-leg, ...}, challenger, status} — the A- prune-vectors (cont 13/15) filed against this record (latent_olympics §4)."],
    "appeals": ["{evidence, newDrillEdges, rescoreDelta, outcome} — re-open with new evidence; lineage grows, legacy earned by performance (latent_olympics §5; cont 27 §3)."]
  },
  "refs": ["string — file:section citations grounding every field (the provenance backbone; e.g. 'cont 22 §7', 'cont 25 §6', 'BAR_A_SKETCH §IT C-IT-6')."],
  "observerRelative": "boolean — true (default). Flags that all scores are projection coefficients under an observer/domain render (cont 32 Part B / cont 22 §6), NOT view-from-nowhere facts — the reason weights are soft."
}

Selection note (NOT a field): ranking is the Pareto non-dominated set over {spread, utility, legacy, rigor} truncated to top-N-per-event (latent_olympics §2) — a weighted-sum total order is forbidden; utility is PRIMARY but still a soft coordinate, not a crown.
